LISTING 11.1 PrefabGenerator.cs
using UnityEngine;
public class PrefabGenerator : MonoBehaviour
{
public GameObject prefab;
void Update()
{
// Whenever we hit the B key we will generate a prefab at the
// position of the original prefab
// Whenever we hit the space key, we will generate a prefab at the
// position of the spawn object that this script is attached to
if (Input.GetKeyDown(KeyCode.B))
{
Instantiate(prefab);
}
if (Input.GetKeyDown(KeyCode.Space))
{
Instantiate(prefab, transform.position, transform.rotation);
}
}
}
5. With the spawn point selected, drag the Lamp prefab onto the Prefab property of the
Prefab Generator component. Now run the scene. Notice how pressing the B key creates a
lamp at its default prefab position and how pressing the spacebar creates an object at the
spawn point.
